  (bank_id, otr_number, module, chapter, context, star, corrected, stem, options, justification, sources)
values
(1, 31, 'Traumatologie', 'Hanche traumatique', NULL, false, true, 'La déformation clinique en flexion de la hanche, abduction et rotation externe, évoque d’emblée:', '[{"l":"A","t":"Une fracture de la diaphyse fémorale.","c":false},{"l":"B","t":"Une fracture trochantérienne.","c":false},{"l":"C","t":"Une luxation de hanche dans sa variété antérieure.","c":true},{"l":"D","t":"Une fracture du col du fémur.","c":false},{"l":"E","t":"Une luxation de la hanche dans sa variété postérieure","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(2, 26, 'Traumatologie', 'Hanche traumatique', NULL, false, true, 'La luxation traumatique de la hanche:', '[{"l":"A","t":"Est fréquente chez le sujet âgé.","c":false},{"l":"B","t":"Une attitude propice de la hanche au traumatisme favorise la luxation.","c":true},{"l":"C","t":"Se voit suite à un traumatisme minime de la hanche.","c":false},{"l":"D","t":"Survient sur un col ostéoporotique","c":false},{"l":"E","t":"Le mécanisme du tableau de bord est le plus souvent mis en cause","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(3, 26, 'Traumatologie', 'Hanche traumatique', NULL, false, true, 'Devant un traumatisme fermé de la hanche chez un sujet de 70 ans suite à une chute de sa hauteur, et qui consulte pour une douleur à la marche avec appui possible sans aucune attitude vicieuse, vous prescrivez (cochez la réponse juste):', '[{"l":"A","t":"Un traitement à base d’antalgiques.","c":false},{"l":"B","t":"Une décharge pour une durée de 03 semaines.","c":false},{"l":"C","t":"Appui protégé par un tuteur externe.","c":false},{"l":"D","t":"Demande d’une radiographie du bassin.","c":true},{"l":"E","t":"Demande d’un bilan inflammatoire VS et CRP.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(4, 26, 'Traumatologie', 'Hanche traumatique', NULL, false, true, 'Une fracture luxation de la hanche classée PIPKIN 2 associe: (Cocher la réponse juste)', '[{"l":"A","t":"Une luxation postérieure de la hanche avec la fracture parcellaire de la tête fémorale","c":false},{"l":"B","t":"Une fracture du cotyle associée à une fracture du col fémoral","c":false},{"l":"C","t":"Une luxation de la hanche associée à une fracture du cotyle","c":false},{"l":"D","t":"Une luxation postérieure de la hanche associée à une fracture de la tête à gros fragment","c":true},{"l":"E","t":"Une luxation postérieure de la hanche associée à une fracture de la tête et une fracture du cotyle","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(5, 26, 'Traumatologie', 'Hanche traumatique', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Quel diagnostic évoquez-vous en première intention', '[{"l":"A","t":"fracture de la diaphyse fémorale","c":false},{"l":"B","t":"fracture pertrochontérienne","c":false},{"l":"C","t":"fracture du col fémoral","c":false},{"l":"D","t":"luxation postérieure de la hanche","c":true},{"l":"E","t":"luxation antérieure de la hanche","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(6, 26, 'Traumatologie', 'Hanche traumatique', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Les radiographies de la hanche de face et de profil réalisés: Cocher la ou les réponses justes', '[{"l":"A","t":"sont suffisantes","c":false},{"l":"B","t":"Doivent être complétée par un faux profil","c":false},{"l":"C","t":"Doivent être complétée par un 3/4 alaire","c":true},{"l":"D","t":"Doivent être complétée par un 3/4 obturateur","c":true},{"l":"E","t":"Doivent être complétée par une tomodensitométrie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(7, 18, 'Traumatologie', 'Amputations des membres', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Le premier geste thérapeutique sur lésion osseuse est: Cocher la réponse juste', '[{"l":"A","t":"la réduction de luxation","c":true},{"l":"B","t":"abstention thérapeutique","c":false},{"l":"C","t":"la mise en extension continue","c":false},{"l":"D","t":"la mise en place d’une prothèse de hanche","c":false},{"l":"E","t":"l’immobilisation plâtrée","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(8, 31, 'Traumatologie', 'Hanche traumatique', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', true, true, 'La déformation clinique en flexion de la hanche, adduction et rotation interne, évoque d’emblée: (cochez la réponse juste)', '[{"l":"A","t":"Une fracture de la diaphyse fémorale","c":false},{"l":"B","t":"Une fracture trochantérienne","c":false},{"l":"C","t":"Une luxation de hanche dans sa variété antérieure","c":false},{"l":"D","t":"Une fracture du col du fémur.","c":false},{"l":"E","t":"Aucune réponse n’est juste.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(9, 26, 'Traumatologie', 'Hanche traumatique', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', true, true, 'La luxation traumatique de la hanche: (cochez la réponse juste)', '[{"l":"A","t":"Est fréquente chez le sujet âgé.","c":false},{"l":"B","t":"Une attitude propice de la hanche au traumatisme est obligatoire.","c":true},{"l":"C","t":"Se voit suite à un traumatisme minime de la hanche.","c":false},{"l":"D","t":"Survient sur un col ostéoporotique.","c":false},{"l":"E","t":"Aucune dc ces propositions n’est juste.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(10, 26, 'Traumatologie', 'Hanche traumatique', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Le diagnostic clinique d’une luxation de hanche dans sa variété postérieure iliaque:', '[{"l":"A","t":"le membre inférieur en abduction rotation interne hanche en extension","c":false},{"l":"B","t":"le membre inférieur en adduction rotation externe hanche en flexion","c":false},{"l":"C","t":"le membre inférieur en adduction rotation interne hanche en extension","c":false},{"l":"D","t":"le membre inférieur en abduction rotation externe hanche en flexion","c":false},{"l":"E","t":"toutes ces réponses sont fausses","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(11, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Une fracture trans-cervicale du col du fémur GARDEN IV chez un sujet jeune:', '[{"l":"A","t":"Est habituellement de très bon pronostic.","c":false},{"l":"B","t":"Nécessite généralement ostéosynthèse","c":true},{"l":"C","t":"Crée souvent un cal vicieux tolérable en l’absence de traitement","c":false},{"l":"D","t":"Les travées osseuses de la tête sont déviées en valgus,","c":false},{"l":"E","t":"N’évolue jamais vers la nécrose céphalique.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(12, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'En cas de fracture engrenée, du col fémoral GARDEN 1:', '[{"l":"A","t":"L’impotence fonctionnelle est relative;","c":true},{"l":"B","t":"La douleur est modérée","c":true},{"l":"C","t":"Le blessé peut décoller le talon du lit;","c":true},{"l":"D","t":"L’attitude vicieuse est caractéristique:","c":false},{"l":"E","t":"Le diagnostic est évident cliniquement","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(13, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Cochez une réponse juste. Dans les fractures du col fémoral l’attitude est en:', '[{"l":"A","t":"Adduction, Rotation externe, Pas de raccourcissement","c":false},{"l":"B","t":"Adduction, Rotation interne, Raccourcissement","c":false},{"l":"C","t":"Abduction, rotation externe, Raccourcissement","c":false},{"l":"D","t":"Abduction, Rotation interne, Raccourcissement","c":false},{"l":"E","t":"Adduction, Rotation externe, Raccourcissement.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(14, 31, 'Traumatologie', 'Hanche traumatique', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', true, true, 'Une fracture cervicale sous capitale engrenée en coxa valga dont l’angle du trait est inférieur à 30° définit:', '[{"l":"A","t":"Type I de Delbet, type III de Pauwels et type IV de Garden","c":false},{"l":"B","t":"Type I de Delbet type II de Pauwels et type I de Garden","c":true},{"l":"C","t":"Type II de Delbet, type III de Pauwels et type Ide Garden","c":false},{"l":"D","t":"Type I de Delbet, type I de Pauwels et type I de Garden","c":false},{"l":"E","t":"Type I de Delbet, type 111 de Pauwels et type Ide Garden","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(15, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Un ou plusieurs des éléments cliniques suivants est (sont) compatible(s) avec le diagnostic de fracture du col du fémur classer Garden IV:', '[{"l":"A","t":"Attitude vicieuse en rotation externe du membre inférieur","c":true},{"l":"B","t":"Attitude vicieuse en adduction du membre inférieur","c":true},{"l":"C","t":"Raccourcissement du membre inférieur","c":true},{"l":"D","t":"Aucune déformation apparente","c":false},{"l":"E","t":"Attitude en flexion de la cuisse sur le bassin","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(16, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Quel traitement doit-on proposer à une femme de 40 ans, en bon état général, victime d’une fracture déplacée, sous-capitale, du col fémoral ?', '[{"l":"A","t":"Extension continue","c":false},{"l":"B","t":"Vissage","c":true},{"l":"C","t":"Enclouage d’Ender","c":false},{"l":"D","t":"Prothèse totale","c":false},{"l":"E","t":"Plâtre pelvi-pédieux après réduction","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(17, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Dans les fractures du col fémoral Garden III, les radiographies pourront mettre en évidence:', '[{"l":"A","t":"Une rupture du cintre cervico-obturateur","c":false},{"l":"B","t":"Une fermeture de l’angle cervico-céphalique de face","c":true},{"l":"C","t":"Une visualisation plus nette du petit trochanter sur le cliché de face","c":true},{"l":"D","t":"Des travées osseuses (de la tête) déviées en valgus","c":false},{"l":"E","t":"Des travées osseuses (de la tête) dans le prolongement de celles du cotyle","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(18, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Un ou plusieurs des éléments cliniques suivants est (ou sont) compatible(s) avec le diagnostic de fracture du col du fémur:', '[{"l":"A","t":"Attitude vicieuse en rotation externe du membre inférieur","c":true},{"l":"B","t":"Attitude vicieuse en adduction du membre inférieur","c":true},{"l":"C","t":"Raccourcissement du membre inférieur","c":true},{"l":"D","t":"Aucune déformation apparente","c":true},{"l":"E","t":"Attitude en flexion de la cuisse sur le bassin","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(19, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Les fractures du col du fémur et du massif trochantérien sont identiques sur certains points. Lequel ou Lesquels ?', '[{"l":"A","t":"Les mécanismes de survenue sont les mêmes chez les jeunes et les personnes âgées","c":true},{"l":"B","t":"L’attitude vicieuse du membre inférieur est différente","c":false},{"l":"C","t":"Le traitement est identique pour les deux types de fractures","c":false},{"l":"D","t":"Évolution et type de complication identiques.","c":false},{"l":"E","t":"Les fractures sont exclusivement intra articulaires","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(20, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Les fractures du col fémoral sont caractérisées par: cocher les réponses justes', '[{"l":"A","t":"fréquente chez le sujet âgé à l’occasion d’un traumatisme violent","c":false},{"l":"B","t":"l’ostéoporose est un facteur favorisant chez le sujet âgé","c":true},{"l":"C","t":"se complique parfois de pseudarthrose en cas de traitement conservateur","c":true},{"l":"D","t":"l’arthroplastie est le traitement habituel chez le sujet jeune","c":false},{"l":"E","t":"le traitement conservateur est toujours indiqué sur le sujet agé","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(21, 31, 'Traumatologie', 'Hanche traumatique', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Une fracture cervicale sous capital engrené en coxa valga dont l’angle du trait est supérieure à 50° définit:', '[{"l":"A","t":"Type I de Delbet, type III de Pauwels et type IV de Garden","c":false},{"l":"B","t":"Type I de Delbet, type II de Pauwels et type I de Garden","c":false},{"l":"C","t":"Type II de Delbet, type III de Pauwels et type I de Garden","c":false},{"l":"D","t":"Type I de Delbet, type I de Pauwels et type II de Garden","c":false},{"l":"E","t":"Type I de Delbet, type III de Pauwels et type I de Garden","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(22, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Les fracture du col fémoral sont:', '[{"l":"A","t":"sont des fractures intracapsulaires vraies","c":true},{"l":"B","t":"exposant aux pseudarthroses et aux nécroses la tête fémoral","c":true},{"l":"C","t":"nécessite un traitement chirurgical rapide","c":true},{"l":"D","t":"fréquente chez le sujet âgé","c":true},{"l":"E","t":"exige dans certains cas un traitement orthopédique chez le sujet jeune","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(23, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', true, true, 'Une fracture trans cervicale du col du fémur chez un vieillard GARDEN IV: (Cochez la réponse juste)', '[{"l":"A","t":"Est habituellement de très bon pronostic.","c":false},{"l":"B","t":"Nécessite généralement une arthroplastie.","c":true},{"l":"C","t":"Crée souvent un cal vicieux tolérable en l’absence de traitement.","c":false},{"l":"D","t":"Les travées osseuses de la tête sont déviées en valgus.","c":false},{"l":"E","t":"N’évolue jamais vers la nécrose céphalique","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(24, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'La classification radiologique de Garden fait intervenir: (la réponse juste)', '[{"l":"A","t":"la direction du trait de fracture","c":false},{"l":"B","t":"l’orientation de la tête fémorale","c":false},{"l":"C","t":"la direction des travées osseuses","c":true},{"l":"D","t":"le déplacement","c":false},{"l":"E","t":"l’angulation","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(25, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'En cas de fracture engrenée, non déplacée du col fémoral: (la ou les réponses justes)', '[{"l":"A","t":"l’impotence fonctionnelle est relative","c":true},{"l":"B","t":"la douleur est modérée","c":true},{"l":"C","t":"le blesser peut décoller le talon du lit","c":true},{"l":"D","t":"l’attitude vicieuse est caractéristique","c":false},{"l":"E","t":"le diagnostic est radiologique","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(26, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Dans les fractures du col du fémur, l’inspection retrouve: (La ou les réponses justes)', '[{"l":"A","t":"rotation interne, Adduction","c":false},{"l":"B","t":"rotation interne, Abduction","c":false},{"l":"C","t":"rotation externe, Adduction","c":true},{"l":"D","t":"rotation externe, Abduction","c":false},{"l":"E","t":"inégalité de longueur de membres","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(27, 10, 'Traumatologie', 'Hanche traumatique', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', true, true, 'Parmi ces propositions concernant les fractures trochantériennes: cochez les propositions justes:', '[{"l":"A","t":"Sont fréquentes chez la femme âgée","c":true},{"l":"B","t":"L’ostéoporose est le facteur de risque le plus déterminant","c":true},{"l":"C","t":"Le but du traitement chez le sujet âgé est d’obtenir la consolidation","c":false},{"l":"D","t":"Elle se complique souvent d’ostéonécrose de la tête fémorale","c":false},{"l":"E","t":"L’ostéosynthèse est le traitement habituel","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(28, 7, 'Traumatologie', 'Complication de l’immobilité et décubitus', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Les fractures du massif trochantérien: RJ(s)', '[{"l":"A","t":"Est une fracture fréquente chez le sujet âgé","c":true},{"l":"B","t":"Son traitement impose la mise en place d’une prothèse","c":false},{"l":"C","t":"Expose souvent à la pseudarthrose","c":false},{"l":"D","t":"Expose aux complications de décubitus en l’absence d’un traitement permettant le levé précoce","c":true},{"l":"E","t":"L’ostéosynthèse est l’indication habituelle","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(29, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Le traitement des fractures trochantériennes et du col du fémur: (Cocher la réponse juste)', '[{"l":"A","t":"Souvent diffère au-delà de 15 jours chez les sujets âgés","c":false},{"l":"B","t":"Le traitement chirurgical est rarement identique","c":false},{"l":"C","t":"Les indications sont retenues en fonction de l’âge de l’activité du patient et du type de la lésion","c":true},{"l":"D","t":"Le traitement chirurgical est exclusivement radical","c":false},{"l":"E","t":"le traitement orthopédique a une place importante dans l’arsenal thérapeutique","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(30, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Les complications les plus fréquentes d’une fracture pertrochantérienne comportent:', '[{"l":"A","t":"La nécrose de la tête fémorale","c":false},{"l":"B","t":"La pseudarthrose du col fémoral","c":false},{"l":"C","t":"Les complications thrombo-emboliques","c":false},{"l":"D","t":"Le cal vicieux","c":true},{"l":"E","t":"L’algodystrophie de hanche","c":false},{"l":"A","t":"(1,2,3) B.(1,3,5) C.(2,3,4) D.(3,4,5) E.(1,2,4)","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(31, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Les complications les plus fréquentes d’une fracture per trochantérienne comportent: Les RJs', '[{"l":"A","t":"La nécrose de la tête fémorale.","c":false},{"l":"B","t":"La pseudarthrose du col fémoral.","c":false},{"l":"C","t":"Les complications thrombo-emboliques.","c":true},{"l":"D","t":"Le cal vicieux.","c":true},{"l":"E","t":"L’algodystrophie de hanche","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(32, 31, 'Traumatologie', 'Hanche traumatique', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Dans la classification d’Ender, les fractures per trochantériennes sont connues comme suit: RJs', '[{"l":"A","t":"Type I: ce sont des fractures per trochantériennes simple.","c":true},{"l":"B","t":"Type III: per trochantérienne stable en coxa valga.","c":false},{"l":"C","t":"Type IV: per trochantérienne en rotation interne avec pénétration bec distale arrondi.","c":false},{"l":"D","t":"Type VI: fracture intertrochantérienne","c":true},{"l":"E","t":"Type VIII: Fracture diaphyso-trochantérienne.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(33, 31, 'Traumatologie', 'Hanche traumatique', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', true, true, 'Quel sera le traitement définitif préféré d’une fracture pertrochantérienne du fémur chez un sujet âgé: cocher les réponses justes', '[{"l":"A","t":"Repos au lit jusqu’à l’indolence puis lever avec l’aide d’un kinésithérapeute","c":false},{"l":"B","t":"Arthroplastie totale de la hanche","c":false},{"l":"C","t":"Ostéosynthèse par DHS ou clou GAMMA sous anesthésie rachidienne ou péridurale","c":true},{"l":"D","t":"Traction-suspension, prévention anti thromboembolique, Kinésithérapie respiratoire","c":false},{"l":"E","t":"Lever précoce analgésique majeur","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(34, 10, 'Traumatologie', 'Ostéopathies reminéralisantes (ostéoporose, ostéomalacie)', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Quelle est parmi ces signes radiographique, celui qui est évocateur d’hyperparathyroïdie primitive ?', '[{"l":"A","t":"Fracture vertébrale","c":false},{"l":"B","t":"Fracture du col fémoral","c":false},{"l":"C","t":"Fissure de Looser Milkman","c":false},{"l":"D","t":"Résorption des houppes phalangiennes","c":true},{"l":"E","t":"Image en miroir","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(35, 26, 'Traumatologie', 'Hanche traumatique', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'L’examen clinique de hanche chez tout nouveau- né est:', '[{"l":"A","t":"Obligatoire à la naissance","c":true},{"l":"B","t":"Obligatoire uniquement si le nouveau-né présente des facteurs de risque favorisant une luxation de la hanche","c":false},{"l":"C","t":"Est un examen de dépistage courant","c":true},{"l":"D","t":"Doit être fait par un pédiatre","c":false},{"l":"E","t":"Toutes asymétrie est suspecte et doit approfondir les explorations","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(36, 26, 'Traumatologie', 'Hanche traumatique', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Dans l’arthrite de la hanche chez enfant: cochez la réponse fausse', '[{"l":"A","t":"Les mouvements de la hanche sont normaux","c":true},{"l":"B","t":"Les mouvements de la hanche sont limites.","c":false},{"l":"C","t":"Attitude vicieuse du membre inferieur en rotation.","c":false},{"l":"D","t":"L’abduction et la rotation interne sont les plus souvent affectées","c":false},{"l":"E","t":"On peut avoir un flessum de la hanche.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(37, 5, 'Traumatologie', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'La ponction articulaire en cas d’ostéoarthrite de la hanche est: (réponse fausse)', '[{"l":"A","t":"un geste urgent","c":false},{"l":"B","t":"un geste diagnostique","c":false},{"l":"C","t":"un geste thérapeutique","c":false},{"l":"D","t":"un geste diagnostique et thérapeutique","c":false},{"l":"E","t":"sans aucun intérêt","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(38, 26, 'Traumatologie', 'Hanche traumatique', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'L’échographie de la hanche permis en cas: (de cocher la réponse fausse)', '[{"l":"A","t":"D’affirmer la présence du liquide","c":false},{"l":"B","t":"D’affirmer l’hypertrophie synoviale","c":false},{"l":"C","t":"De faire une ponction guidée","c":false},{"l":"D","t":"De préciser la nature de liquide et de sa qualité","c":true},{"l":"E","t":"Au terme de cet examen on décidera de la ponction articulaire","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(39, 26, 'Traumatologie', 'Hanche traumatique', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'La ponction articulaire en cas d’arthrite de la hanche: (à cocher la réponse fausse)', '[{"l":"A","t":"Un but diagnostic: voir la nature de liquide et faire l’ECB","c":false},{"l":"B","t":"Un but thérapeutique: évacuer le liquide et faire un lavage articulaire","c":false},{"l":"C","t":"Un double but thérapeutique et diagnostique","c":false},{"l":"D","t":"Peu d’intérêt dans le diagnostic et le traitement de l’arthrite","c":true},{"l":"E","t":"La ponction articulaire c’est un acte chirurgical","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(40, 31, 'Traumatologie', 'Hanche traumatique', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'L’épiphysiolyse se caractérise par: (Réponse fausse)', '[{"l":"A","t":"glissement non traumatique de la calotte épiphysaire fémorale","c":false},{"l":"B","t":"à la radiologie: la ligne de KlEIN est perpendiculaire au bord supérieur du col fémoral","c":true},{"l":"C","t":"une urgence thérapeutique","c":false},{"l":"D","t":"suppression immédiate de l’appui","c":false},{"l":"E","t":"traitement est chirurgical: vissage","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(41, 29, 'Traumatologie', 'Algoneurodystrophie', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', true, true, 'Les circonstances et causes suivantes peuvent être à l’origine d’un SDRC 1: RJ(s)', '[{"l":"A","t":"Prise médicamenteuse de Phénobarbital (Gardénal) ou isoniazide (Rimifon D).","c":true},{"l":"B","t":"Un diabète","c":true},{"l":"C","t":"Une Hémiplégie","c":true},{"l":"D","t":"Un traumatisme minime","c":true},{"l":"E","t":"Idiopathique","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(42, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Dans les fractures du col fémoral l’attitude est en: La RJ', '[{"l":"A","t":"Adduction,Rotation externe,Pas de raccourcissement","c":false},{"l":"B","t":"Adduction,Rotation interne,Raccourcissement","c":false},{"l":"C","t":"Abduction,rotation externe,Raccourcissement","c":false},{"l":"D","t":"Abduction,Rotation interne,Raccourcissement","c":false},{"l":"E","t":"Adduction,Rotation externe,Raccourcissement","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(43, 31, 'Traumatologie', 'Hanche traumatique', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Une fracture cervicale sous capitale engrenée en coxa valga dont l’angle du trait est ****<****30° définit:', '[{"l":"A","t":"Type ide lbet,type iii pauwels et type iv garden","c":false},{"l":"B","t":"TypeIDelbettypeIIPauwelsettypeIGarden","c":false},{"l":"C","t":"Type i ide lbet,type iii pauwels et type i garden","c":false},{"l":"D","t":"Type ide lbet,type i pauwels et type i garden","c":true},{"l":"E","t":"Type ide lbet,type iii pauwels et type i garden","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(44, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Un ou plusieurs des éléments cliniques suivants est (sont) compatible(s) avec le diagnostic de fracture du col du fémur classée Garden IV:', '[{"l":"A","t":"Attitudevicieuseenrotationexternedumembreinf","c":true},{"l":"B","t":"Attitude vicieuse en adduction du membre inferieur","c":true},{"l":"C","t":"Raccourcissement du membre inferieur","c":true},{"l":"D","t":"Aucune deformation apparente","c":false},{"l":"E","t":"Attitudeenflexiondelacuissesurlebassin","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(45, 26, 'Traumatologie', 'Hanche traumatique', 'Cas clinique: Après un accident de voiture grave, un homme de 40 ans est transporté à l’hôpital en état de choc avec une déformation importante du membre inférieur, en adduction rotation interne.', false, true, 'Devant un traumatisme fermé de la hanche chez un sujet de 70 ans suite à une chute de sa hauteur, et qui consulte pour une douleur à la marche avec appui possible sans aucune attitude vicieuse, vous prescrivez: La RJ', '[{"l":"A","t":"Un traitement a base d’antalgiques.","c":false},{"l":"B","t":"Une decharge pour une duree de03semaines.","c":false},{"l":"C","t":"Appui protege par un tuteur externe.","c":false},{"l":"D","t":"Demande d’une radiographie du bassin.","c":true},{"l":"E","t":"Demande d’un bilan inflammatoire vset crp.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(46, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Le traitement le plus adapté aux fractures per trochantériennes du sujet àgé de 75 ans est-il ? La/Les RJ', '[{"l":"A","t":"La traction prolongee jusqu’a consolidation","c":false},{"l":"B","t":"L’immobilisation plâtrée par appareil pelvi pédieux","c":false},{"l":"C","t":"L’implantation d’une prothese cephalique","c":false},{"l":"D","t":"Une osteosynthese par clou-gamma ou vis-plaque","c":true},{"l":"E","t":"Aucune des reponses precedentes","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(47, 10, 'Traumatologie', 'Hanche traumatique', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Parmi ces propositions concernant les fractures trochantériennes: Les RJ', '[{"l":"A","t":"Sont frequentes chez la femme agee","c":true},{"l":"B","t":"L’ostéoporose est le facteur de risque le plus déterminant","c":true},{"l":"C","t":"Lebutdutraitementchezlesujetâgéestd’obtenir la consolidation","c":false},{"l":"D","t":"Elles e complique souvent d’osteonecrose dela tete fémorale","c":false},{"l":"E","t":"L’osteosynthese est le traitement habituel","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(48, 7, 'Traumatologie', 'Complication de l’immobilité et décubitus', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Les fractures du massif trochantérien: La/Les RJ', '[{"l":"A","t":"Est une fracture frequente chez les uj etage","c":true},{"l":"B","t":"Son traitement impose la mise en place d’une prothèse","c":false},{"l":"C","t":"Exposes ouv ent ala pseudarthrose","c":false},{"l":"D","t":"Expose aux complications de décubitus en l’absence d’un traitement permettant l eleve precoce","c":true},{"l":"E","t":"L’osteosynthese est l’indication habituelle","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
