(115, 5, 'Traumatologie', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', NULL, false, true, 'L’abcès sous périosté dans l’ostéomyélite doit être traité par:', '[{"l":"A","t":"antibiothérapie + immobilisation plâtrée","c":false},{"l":"B","t":"antibiothérapie seule","c":false},{"l":"C","t":"évacuation chirurgicale de l’abcès + Antibiothérapie + Immobilisation plâtrée","c":true},{"l":"D","t":"forage de l’os + Antibiothérapie + Immobilisation plâtrée","c":false},{"l":"E","t":"surveillance jusqu’à apparition de signes osseux pour traiter","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(116, 1, 'Traumatologie', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', NULL, true, true, 'Après une sédation d’une dizaine de jours, des dlrs pulsatiles nocturnes apparaissent localisées au fémur. Quelle(s) complication(s) recherchez-vous ?', '[{"l":"A","t":"Une arthrite du genou","c":false},{"l":"B","t":"Une phlebite","c":false},{"l":"C","t":"Un abcès sous périosté","c":true},{"l":"D","t":"Un décollement épiphysaire","c":false},{"l":"E","t":"Une escarre sous plâtre","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Résidanat en poche – Traumato-Orthopédie (Nadji 85)"]'::jsonb),
(117, 5, 'Traumatologie', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', NULL, false, true, 'Au stade de début de l’ostéomyélite: la RJ', '[{"l":"A","t":"RX est normal","c":true},{"l":"B","t":"On trouve des lacunes métaphysaires","c":false},{"l":"C","t":"Des séquestres osseux","c":false},{"l":"D","t":"Un périoste d’aspect dense et décollé","c":false},{"l":"E","t":"Un aspect en sucre mouillé","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(118, 8, 'Traumatologie', 'Généralités des fractures', NULL, false, true, 'Parmi les termes suivants, lequel correspond à une section totale d’un nerf ?', '[{"l":"A","t":"Axonotmesis","c":false},{"l":"B","t":"Neurotmesis","c":true},{"l":"C","t":"Neurapraxie","c":false},{"l":"D","t":"Neurolyse","c":false},{"l":"E","t":"Epineurectomie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(119, 8, 'Traumatologie', 'Généralités des fractures', NULL, false, true, 'On peut avoir une lésion nerveuse périphérique post traumatique:', '[{"l":"A","t":"Par englobement d’un nerf périphérique dans un cal de consolidation","c":true},{"l":"B","t":"Étirements du nerf périphérique après consolidation vicieuse","c":true},{"l":"C","t":"Immédiatement en absence d’une lésion osseuse","c":true},{"l":"D","t":"Après une fracture","c":true},{"l":"E","t":"Par injection sous-cutanée","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(120, 8, 'Traumatologie', 'Généralités des fractures', NULL, true, true, 'Cette lésion nerveuse est survenue: RF(s)', '[{"l":"A","t":"Par englobement du nerf dans un cal de consolidation.","c":true},{"l":"B","t":"Par un étirement lors d’une inclinaison forcée de la tête et du cou lors du traumatisme.","c":false},{"l":"C","t":"Peut survenir immédiatement en absence d’une lésion nerveuse.","c":false},{"l":"D","t":"Par rupture lors d’une inclinaison forcée de de la tête et du cou lors du traumatisme.","c":false},{"l":"E","t":"Suite à une lésion vasculaire.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(121, 8, 'Traumatologie', 'Généralités des fractures', NULL, true, true, 'Parmi les termes suivants, lequel correspond à une section totale de cette lésion nerveuse. (Cochez la réponse juste);', '[{"l":"A","t":"Axonotmésis","c":false},{"l":"B","t":"Neurotmésis","c":true},{"l":"C","t":"Neurapraxie","c":false},{"l":"D","t":"Neurolyse","c":false},{"l":"E","t":"Epineurectomie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(122, 8, 'Traumatologie', 'Généralités des fractures', NULL, false, true, 'Concernant la neurapraxie: (la ou les réponses justes)', '[{"l":"A","t":"Interruption temporaire de la conduction nerveuse","c":true},{"l":"B","t":"Perte de la continuité axonale","c":false},{"l":"C","t":"De récupération rapide après la levée de la compression","c":true},{"l":"D","t":"Sa réparation se fait par suture ou greffe","c":false},{"l":"E","t":"C’est le degré I de Sunderland.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(123, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Quelle est l’urgence qui doit être opérée en premier en cas de lésions associées dans le cadre d’un poly traumatisme ? La/Les RJ', '[{"l":"A","t":"Plaie abdominale.","c":false},{"l":"B","t":"Fracture ouverte du femur","c":false},{"l":"C","t":"Hematome extradural","c":true},{"l":"D","t":"Ischemie du membres u peri eur","c":false},{"l":"E","t":"Hémothorax","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(124, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Selon la classification de SEDDON la lesion type neurapraxie est: La/Les RJ', '[{"l":"A","t":"Arret dela conduction axonique avec recuperation rapide.","c":true},{"l":"B","t":"Section d une rf avec perte de conduction definitive.","c":false},{"l":"C","t":"Section de l’axone avec perte de conduction.","c":false},{"l":"D","t":"Gaine fasciculaire lesee mais epinevre intact.","c":false},{"l":"E","t":"Tube endo neurallese mais saine fasciculaire intacte.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","Annales classées","EMD OTR section A","EMD (section A) PROMO 2017"]'::jsonb),
(125, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Les fractures per trochantériennes sont plus exposées dans leur évolutions que les fractures transcervicales, au risque de: La/Les RJ', '[{"l":"A","t":"Pseudarthrose","c":false},{"l":"B","t":"Cal vicieux","c":true},{"l":"C","t":"Complications de decubitus","c":false},{"l":"D","t":"Necrose ischemique dela tete femorale","c":false},{"l":"E","t":"Raideursecondairedelahanche","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(126, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Les fractures per trochantériennes: La/Les RF', '[{"l":"A","t":"Evolution est souvent défavorable avec un certain nombre de complications qui sont osteonecrose delatêtefémoraleetPseudarthroseducolfémorale.","c":true},{"l":"B","t":"Le traitement est chirurgical mais rarement conservateur.","c":true},{"l":"C","t":"L’indication therapeutique est souvent liee aun seul parametre l’age.","c":true},{"l":"D","t":"Facteurs d’instabilité de ces fractures sont representes exclusivement parle s facteurs osseux.","c":true},{"l":"E","t":"Endehorsdetouttraitementlaconsolidationsefait en cal vicieux","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(127, 36, 'Traumatologie', 'Généralités des fractures', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Evolution des fractures de la diaphyse fémorale est compromise par la survenue de complications tardives suivantes: La/Les RJ', '[{"l":"A","t":"La pseudarthrose.","c":true},{"l":"B","t":"Le cal vicieux.","c":true},{"l":"C","t":"Raideur du genou.","c":true},{"l":"D","t":"Lesion du ligament croise posterieur","c":false},{"l":"E","t":"Embolie graisseuse.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(128, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Une fracture ouverte de type I de la classification de CAUCHOIX et DUPARC nécessite:', '[{"l":"A","t":"Antibiotiques","c":true},{"l":"B","t":"Serotherapie antitetanique.","c":true},{"l":"C","t":"Peut etre traite comme une fracture fermee","c":true},{"l":"D","t":"Necessite une fixation externe","c":false},{"l":"E","t":"Est de mauvais pronostic","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(129, 39, 'Traumatologie', 'Fracture du cou-de-pied : fracture malléolaire, fracture du pilon tibial', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Une fracture ouverte de type III de la classification de CAUCHOIX et DUPARC nécessite:', '[{"l":"A","t":"Antibiotiques.","c":true},{"l":"B","t":"Serotherapie antitetanique.","c":true},{"l":"C","t":"Osteosynthese endogene.","c":false},{"l":"D","t":"Osteosynthese exogene.","c":true},{"l":"E","t":"Pansement sterile","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(130, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Le déplacement qui ne doit jamais être toléré même minime dans les fractures des os longs est: La RJ', '[{"l":"A","t":"Le decalage.","c":true},{"l":"B","t":"Le chevauchement.","c":false},{"l":"C","t":"La translation","c":false},{"l":"D","t":"L’Angulation.","c":false},{"l":"E","t":"Aucune reponse n’est juste.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(131, 1, 'Traumatologie', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'La fracture en « bois vert » est: La/Les RJ', '[{"l":"A","t":"Une fracture complete","c":false},{"l":"B","t":"Une fracture unie corticale","c":true},{"l":"C","t":"Unefracturesouspériostée","c":true},{"l":"D","t":"Une fracture frequente chez l’adulte","c":false},{"l":"E","t":"Desiègemétaphysaire","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(132, 1, 'Traumatologie', 'Généralités des fractures', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Les fractures de l’enfant sont particulières:', '[{"l":"A","t":"Le trt orthopedique preserve l’hematome fracturaire","c":true},{"l":"B","t":"Lafractureplastiqueestdesiègemétaphysaire","c":false},{"l":"C","t":"Lafractureenmottedebeurreestdebonpronostic","c":true},{"l":"D","t":"Delais de consolidation inferieurs ace uxde l’adulte","c":true},{"l":"E","t":"La fracture en cheveux est frequente apres4ans.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(133, 1, 'Traumatologie', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Le remodelage osseux: Les RJ', '[{"l":"A","t":"Il corrige les cals vicieux en decalage","c":false},{"l":"B","t":"Plus l’enfant est jeune plus les chances de remodelage sont grandes","c":true},{"l":"C","t":"Il est plus important quand la fracture est proche d’un cartilage fertile","c":true},{"l":"D","t":"Il corrige les cals vicieux en angulation","c":true},{"l":"E","t":"Toutes les reponses sont justes","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(134, 1, 'Traumatologie', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Le décollement épiphysaire type 1 est:', '[{"l":"A","t":"Presente un risque eleve de raideur articulaire","c":false},{"l":"B","t":"Est un décollement épiphysaire avec fracture d’un coinmétaphysaire","c":false},{"l":"C","t":"La reduction peut se faire a vif","c":false},{"l":"D","t":"La contention par attelle plâtrée après réduction estnécessaire","c":true},{"l":"E","t":"Est un decollement epiphysaire pur","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(135, 1, 'Traumatologie', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Le décollement épiphysaire type 5:', '[{"l":"A","t":"Fracture métaphyso-épiphysaire qui traverse cartilageconjugal","c":false},{"l":"B","t":"Lesion par compression verticale","c":true},{"l":"C","t":"Le diagnostic peut etre tardif sur des sequelles","c":true},{"l":"D","t":"La fixation se fait par des broches ou une vis","c":false},{"l":"E","t":"La survenue d’epiphysodeses est frequente","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(136, 1, 'Traumatologie', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Le remodelage osseux est: La/Les RJ', '[{"l":"A","t":"La capacité de l’os s’incurver sans se rompre lors d’untraumatisme","c":false},{"l":"B","t":"La capacité de l’os à corriger une angulation sous l’effet des contraintes del’appui","c":true},{"l":"C","t":"Permet la correction de certaines déformations angulaires","c":true},{"l":"D","t":"Permet la correction de certains décalages et de certaines rotations","c":false},{"l":"E","t":"Toutes les reponses sont justes","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(137, 1, 'Traumatologie', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Le périoste de l’enfant est: La/Les RJ', '[{"l":"A","t":"Plus epais que chez l’adulte","c":true},{"l":"B","t":"Estpeurésistantetdoncserompttrèsfacilement","c":false},{"l":"C","t":"A un rôle dans la consolidation en produisant un hématomeen2à3semaines","c":false},{"l":"D","t":"Lors dela reduction des fractures il peut etre utilise comme attelle interne","c":true},{"l":"E","t":"Toutes les reponses sont fausses","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(138, 1, 'Traumatologie', 'Généralités des fractures', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'La fracture en motte de beurre: La/Les RJ', '[{"l":"A","t":"Une fracture-tassement sans solution de continuite","c":true},{"l":"B","t":"Presente une douleurs ans deformation","c":true},{"l":"C","t":"Consolidation est rapide","c":true},{"l":"D","t":"Aucuneséquellesurlacroissancen’estpossible","c":true},{"l":"E","t":"Le deplacements e faite n decalage.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(139, 1, 'Traumatologie', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Quel diagnostic évoquer-vous ? La/Les RJ', '[{"l":"A","t":"Arthrites epti que du genou.","c":false},{"l":"B","t":"Osteomyelite aigue.","c":true},{"l":"C","t":"Hémarthrose","c":false},{"l":"D","t":"Rhumatisme articulaire aigue.","c":false},{"l":"E","t":"Decollement epiphysaire.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(140, 5, 'Traumatologie', 'Infections ostéo-articulaires (ostéoarthrite, ostéomyélite)', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'L’abcès sous périosté dans l’ostéomyélite doit être traité par:', '[{"l":"A","t":"Antibiothérapie+immobilisation platree","c":false},{"l":"B","t":"Antibiotherapie seule","c":false},{"l":"C","t":"Évacuation chirurgicale de l’abcès + ATB + Immobilisation platree","c":true},{"l":"D","t":"Forage de l’os + Antibiothérapie + Immobilisation plâtrée","c":false},{"l":"E","t":"Surveillance jusqu’a apparition des ignes osseux pour traiter","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(141, 1, 'Traumatologie', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Après une sédation d’une dizaine de jours, des douleurs pulsatiles nocturnes apparaissent localisées au fémur. Quelle(s) complication(s) recherchez-vous ?', '[{"l":"A","t":"Une arthrite du genou","c":false},{"l":"B","t":"Une phlebite","c":false},{"l":"C","t":"Un abces sous perioste","c":true},{"l":"D","t":"Un decollement epiphysaire","c":false},{"l":"E","t":"Une escarres ous platre","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(142, 37, 'Traumatologie', 'Traumatismes osseux du genou', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Cette lésion nerveuse est survenue: La/Les RF', '[{"l":"A","t":"Parenglobementdunerfdansuncaldeconsolidation.","c":true},{"l":"B","t":"Par un etirement lors d’une inclinaison forcée de la tete etdu cou lors du traumatisme.","c":false},{"l":"C","t":"Peut survenir immédiatement en absence d’une lésionnerveuse.","c":false},{"l":"D","t":"Par rupture lors d’une inclinaison forcée de de la tete etdu cou lors du traumatisme.","c":false},{"l":"E","t":"Suite a une lesion vasculaire.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(143, 37, 'Traumatologie', 'Traumatismes osseux du genou', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Parmi les lésions suivantes associées chez le même blessé, l’une doit être opérée la première. Laquelle ?', '[{"l":"A","t":"Plaie abdominale.","c":false},{"l":"B","t":"Fracture ouverte du fémur","c":false},{"l":"C","t":"Hématome extra-dural","c":true},{"l":"D","t":"Ischémie du membre supérieur","c":false},{"l":"E","t":"Hémothorax","c":false}]'::jsonb, NULL, '["Annales classées","EMD OTR section B"]'::jsonb),
(144, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'A partir de quel délai de non consolidation parle-t-on de pseudarthrose au membre inférieur: réponse juste', '[{"l":"A","t":"3 mois","c":false},{"l":"B","t":"6 mois","c":true},{"l":"C","t":"9mois","c":false},{"l":"D","t":"12 mois","c":false},{"l":"E","t":"1 mois","c":false}]'::jsonb, NULL, '["Annales classées","Rattrapage OTR promo 2019"]'::jsonb),
(145, 1, 'Traumatologie', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Quelle est (sont) la (les) réponse(s) juste(s) concernant le cal vicieux:', '[{"l":"A","t":"c’est une consolidation osseuse en position non-anatomique","c":true},{"l":"B","t":"peut-être secondaire à un déplacement secondaire de la fracture","c":true},{"l":"C","t":"est toujours bien toléré","c":false},{"l":"D","t":"chez l’enfant il se comige avec la croissance","c":true},{"l":"E","t":"il peut nécessiter une chirurgie de réaxation","c":true}]'::jsonb, NULL, '["Annales classées","Rattrapage OTR promo 2019"]'::jsonb),
(146, 37, 'Traumatologie', 'Traumatismes osseux du genou', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'A propos de la traumatologie en général, cochez la seule bonne réponse parmi ces 5 énoncés.', '[{"l":"A","t":"Une fracture ouverte de grade 1 au tibia impose une stabilisation par fixateur externe","c":false},{"l":"B","t":"Une fracture de fatigue n’intéresse qu’un os pathologique","c":false},{"l":"C","t":"Une fracture comminutive n’est qu’une fracture partielle, ne rompant qu’une seule corticale","c":false},{"l":"D","t":"Une prophylaxie antitétanique est indiquée en cas de fracture ouverte","c":true},{"l":"E","t":"Un enclouage médullaire impose l’ouverture du foyer de fracture","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(147, 37, 'Traumatologie', 'Traumatismes osseux du genou', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'A propos des fractures ouvertes, toutes les affirmations suivantes sont vraies, SAUF UN Laquelle ?', '[{"l":"A","t":"Le pronostic d’une fracture ouverte est dominé par le risque infectieux","c":false},{"l":"B","t":"Le parage de la plaie est un geste primordial dans l’évolution d’une fracture ouverte","c":false},{"l":"C","t":"Une fracture ouverte consolide moins vite qu’une fracture fermée","c":false},{"l":"D","t":"Un fixateur externe est un moyen d’ostéosynthèse utilisable dans ces fractures","c":false},{"l":"E","t":"L’embolie graisseuse est plus fréquente dans les fractures ouvertes.","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(148, 1, 'Traumatologie', 'Généralités sur les fractures de l’enfant et les traumatismes du cartilage de croissance', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Parmi les affirmations suivantes, une seule est correct Laquelle ?', '[{"l":"A","t":"La consolidation des fractures n’est possible que si l’artère nourricière est intacte","c":false},{"l":"B","t":"La consolidation d’une fracture comminutive n’est possible que grâce à la chirurgie","c":false},{"l":"C","t":"La consolidation d’une fracture est plus rapide chez un adulte que chez un enfant","c":false},{"l":"D","t":"La consolidation d’une fracture est plus rapide en cas de fracture fermée qu’en cas de fracture ouverte","c":true},{"l":"E","t":"La consolidation d’une fracture est plus rapide quand elle est opéré","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(149, 37, 'Traumatologie', 'Traumatismes osseux du genou', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'L’os nouveau se formant lors de la guérison spontanée d’une fracture diaphysaire non opérée et dont les fragments sont bien alignés et en contact se réalise au départ:', '[{"l":"A","t":"Du périoste","c":false},{"l":"B","t":"De l’endoste","c":false},{"l":"C","t":"Des deux corticales en regard","c":false},{"l":"D","t":"Du périoste et de l’endoste","c":true},{"l":"E","t":"De l’artère nourricière de la diaphyse","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(150, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Lors de la prise en charge et la surveillance du traitement d’un enfant porteur d’une fracture supra-condylienne du coude vous avez à craindre:', '[{"l":"A","t":"Un problème vasculaire périphérique","c":true},{"l":"B","t":"Un déficit neurologique radial et cubital","c":true},{"l":"C","t":"Un déplacement sous plâtre","c":true},{"l":"D","t":"Un cal vicieux","c":true},{"l":"E","t":"Une pseudarthrose","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(151, 29, 'Traumatologie', 'Algoneurodystrophie', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Indiquez, parmi les suivantes la ou les propositions exactes. L’algodystrophie post-traumatique se rencontre:', '[{"l":"A","t":"Le plus souvent après une fracture ouverte","c":false},{"l":"B","t":"Le plus souvent chez le diabétique insulino-dependant","c":false},{"l":"C","t":"Même après un traumatisme minime","c":true},{"l":"D","t":"Exclusivement après une intervention chirurgicale","c":false},{"l":"E","t":"Fréquemment chez les sujets anxieux","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(152, 37, 'Traumatologie', 'Traumatismes osseux du genou', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'En pathologie traumatique des nerfs la neurapraxie a une signification très précis Laquelle ?', '[{"l":"A","t":"Section complète du nerf","c":false},{"l":"B","t":"Perte de substance nerveuse","c":false},{"l":"C","t":"Sidération nerveuse","c":true},{"l":"D","t":"Section partielle du nerf","c":false},{"l":"E","t":"Section nerveuse avec conservation de la périnèvre","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(153, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Indiquez parmi les propositions suivantes la ou les affirmations exactes concernant les fractures transcervicales du fémur engrenées en coxa valga, chez un adulte jeune:', '[{"l":"A","t":"Elles ne comportent pas de risque de nécrose ischémique","c":false},{"l":"B","t":"Elles peuvent se déplacer dans les premières semaines après l’accident","c":true},{"l":"C","t":"Elles sont traitées habituellement par arthroplastie","c":false},{"l":"D","t":"Elles sont traitées habituellement par suspension simple","c":true},{"l":"E","t":"Elles comportent un risque important de pseudarthrose","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(154, 31, 'Traumatologie', 'Fracture du fémur proximal (col du fémur et massif trochantérien)', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Une fracture trans-cervicale du fémur chez le vieillard type Garden IV:', '[{"l":"A","t":"Consolide habituellement en trois mois","c":false},{"l":"B","t":"Crée souvent un cal vicieux","c":false},{"l":"C","t":"Nécessite en général une arthroplastie céphalique","c":true},{"l":"D","t":"Entraîne un pourcentage moyen de decès de 20%","c":true},{"l":"E","t":"Est très thrombogène","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(155, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Une pseudarthrose au niveau d’un foyer de fracture de jambe peut être favorisée par un ou plusieurs des facteurs suivants:', '[{"l":"A","t":"Le siège du trait","c":true},{"l":"B","t":"Une thrombose veineuse concomitante","c":false},{"l":"C","t":"L’obliquité de la console de stabilité","c":true},{"l":"D","t":"La présence d’autres fractures sur le membre","c":true},{"l":"E","t":"Une infection","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(156, 6, 'Traumatologie', 'Arthrose (hanche, genou)', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Parmi ces complications, quelles sont celles qu’on peut attribuer à une fracture articulaire:', '[{"l":"A","t":"Raideur","c":true},{"l":"B","t":"Pseudarthrose","c":false},{"l":"C","t":"Cal vicieux","c":true},{"l":"D","t":"Arthrose","c":true},{"l":"E","t":"Toutes les réponses sont fausses","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(157, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Quelle est la complication précoce la plus redoutée dans les fractures de la diaphyse fémorale ?', '[{"l":"A","t":"L’embolie graisseuse","c":true},{"l":"B","t":"La Pseudarthrose","c":false},{"l":"C","t":"L’ouverture cutanée","c":false},{"l":"D","t":"Le Cal vicieux","c":false},{"l":"E","t":"Lésion du nerf sciatique","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(158, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Parmi les complications des fractures des deux os de la jambe, cochez la (les) réponse(s) juste(s):', '[{"l":"A","t":"Ouverture cutanée","c":true},{"l":"B","t":"Cal vicieux après traitement orthopédique","c":true},{"l":"C","t":"Pseudarthrose après traitement chirurgical","c":true},{"l":"D","t":"Thrombose veineuse profonde","c":true},{"l":"E","t":"Toutes les réponses sont fausses","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(159, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'L’évolution des fractures de la diaphyse fémorale est compromise par la survenue des complications tardives suivantes: La/Les RJ', '[{"l":"A","t":"La pseudarthrose.","c":true},{"l":"B","t":"Le cal vicieux.","c":true},{"l":"C","t":"Raideur du genou.","c":true},{"l":"D","t":"Lésion des ligaments croise postérieur.","c":false},{"l":"E","t":"Embolie graisseuse","c":false}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
(160, 37, 'Traumatologie', 'Traumatismes osseux du genou', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Selon la classification de SEDDON la lésion type neurapraxie est: La/Les RJ', '[{"l":"A","t":"Arrêt de la conduction axonique avec récupération rapide.","c":true},{"l":"B","t":"Section du nerf avec perte de conduction définitive.","c":false},{"l":"C","t":"Section de l’axone avec perte de conduction.","c":false},{"l":"D","t":"Gaine fasciculaire lésée mais épinèvre intact.","c":false},{"l":"E","t":"Tube endo-neural lésé mais gaine fasciculaire intacte.","c":false}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
(161, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Une fracture ouverte de jambe mal traitée peut évoluer ou entrainer les complications suivantes: La/Les RJ', '[{"l":"A","t":"Une pseudarthrose","c":true},{"l":"B","t":"Un raccourcissement","c":true},{"l":"C","t":"Un retard de consolidation","c":true},{"l":"D","t":"Des troubles trophiques","c":true},{"l":"E","t":"Une ostéite","c":true}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
(162, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, true, 'Par rapport au traitement orthopédique, le traitement chirurgicar/gyar guvert d’une fracture de jambe, a les inconvénients suivants:', '[{"l":"A","t":"Nécessité de contrôles radiographiques répétés","c":false},{"l":"B","t":"Consolidation retardée","c":false},{"l":"C","t":"Risque de raideur","c":false},{"l":"D","t":"Risque infectieux","c":true},{"l":"E","t":"Risque thromboembolique","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(163, 1, 'Traumatologie', 'Généralités des fractures', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'La classification de SALTER et HARRIS des décollements épiphysaires est la suivante: (Cochez la ou les réponses justes)', '[{"l":"A","t":"Type 1: décoilernent épiphysaire avec trait métaphysaine saire avec trait épiphysaire","c":false},{"l":"B","t":"Type 2: déccilement épiphysaire","c":false},{"l":"C","t":"Type 3 décollement épiphysaire pur","c":false},{"l":"D","t":"Type 4: déccilement épiphysaire à trait métaphyso-épiphysare","c":false},{"l":"E","t":"Type 5: écrasement du cartilage de croissance Universite Grze","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(164, 17, 'Chirurgie pédiatrique', 'Maladies luxantes de la hanche', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'La durée de traitement d’une hanche lusée réductible chez le bébé de moins de 4 mois(en cas de maladie luxante de la hanche) est de: (cochez la réponse juste)', '[{"l":"A","t":"3 mois à plein temps","c":false},{"l":"B","t":"4 mois à plein temps","c":false},{"l":"C","t":"3 mois à plein temps et 2h 3 mois en nocturne","c":false},{"l":"D","t":"4 mois à plein temps et 2 a 3 mois en nocturne","c":false},{"l":"E","t":"5 mois a plein temps et 1 & 2 mois en nocturne Q 19. La bilan de la scoliose cochez les repenses justes","c":false},{"l":"A","t":"Repose sur un interrogatoire et un examen clinique complet chez un enfant complètement dévêtu.","c":false},{"l":"B","t":"Comporte la recherche des signes cutanés, examen neurologique, bilan articulaire.","c":false},{"l":"C","t":"Comporte les mensurations au ruban mètres pour apprécier les inégalités de longueur.","c":false},{"l":"D","t":"Comporte une appréciation de la maturation osseuse par des radiographies du bassin.","c":false},{"l":"E","t":"L’appréciation des caractères sexuels secondaires par la classification de Risser. Q 20. Le traitement des infections ostéo-articulaires comprend; cochez la réponse juste","c":false},{"l":"A","t":"Hospitalisation et conditionnement.","c":false},{"l":"B","t":"Bi-antibiothérapie par vole veineuse d’abord probabiliste puis en fonction de Antibiogramme.","c":false},{"l":"C","t":"Immobilisation plâtre.","c":false},{"l":"D","t":"En cas d’épanchement intra-articulaire; la ponction articulaire n’est pas nécessaire.","c":false},{"l":"E","t":"Ponction métaphysaire ou bien drainage chirurgicale en cas d’aboés sous périosté.","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(165, 8, 'Traumatologie', 'Généralités des fractures', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, true, 'Au cours de la consolidation osseuse, les contraintes suivantes sont nétastes pour la consolidation', '[{"l":"A","t":"Contraintes en compression","c":false},{"l":"B","t":"Contraintes en cisaillement","c":true},{"l":"C","t":"Contraintes en flexion","c":true},{"l":"D","t":"Contrainte en rotation (torsion)","c":true},{"l":"E","t":"Contraintes professionnelles","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(166, 8, 'Traumatologie', 'Généralités des fractures', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, true, 'Les anomalies (alles) de le la consolidation sont', '[{"l":"A","t":"Diagnostiqués cliniquement","c":true},{"l":"B","t":"Diagnostiqués radiologiquement","c":true},{"l":"C","t":"Retrouvées que si le traitement est orthopédique","c":false},{"l":"D","t":"ne surviennent qu’après guérison totale.","c":false},{"l":"E","t":"Peuvent ébe asymptomatiques","c":true}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(167, 11, 'Traumatologie', 'Boiterie chez l’enfant', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'Le traitement des infections ostéo-articulaires comprend; cochez les réponses justes.', '[{"l":"A","t":"Hospitalisation et conditionnement.","c":false},{"l":"B","t":"Bi-antibiothérapie par voie veineuse; d’abord probabiliste puis en fonction de Antibiogramme.","c":false},{"l":"C","t":"Immobilisation plâtre.","c":false},{"l":"D","t":"En cas d’épanchement intra-articulaire; la ponction articulaire n’est pas nécessaire.","c":false},{"l":"E","t":"Ponction métaphysaire ou bien drainage chirurgicale en cas d’abcès sous périosté. Q 25. L’EPIPHYSIOLYSE fémoral se déclare: Cochez la ou les réponses justes:","c":false},{"l":"A","t":"Avant l’âge de 10 ans","c":false},{"l":"B","t":"Par une boiterie d’esquive","c":false},{"l":"C","t":"Par boiterie par plongeon","c":false},{"l":"D","t":"Par boiterie par rééquilibration","c":false},{"l":"E","t":"Le déplacement est le plus souvent progressif","c":false}]'::jsonb, NULL, '["Rattrapage OTR promo 2019"]'::jsonb),
(168, 19, 'Traumatologie', 'Ceinture scapulaire', NULL, false, true, 'Les critères de mauvais pronostic des fractures Trans cervicales de l’extrémité supérieure du fémur sont liés à un ou plusieurs des facteurs suivants:', '[{"l":"A","t":"Le caractère vertical du trait de fracture","c":true},{"l":"B","t":"Un déplacement important","c":true},{"l":"C","t":"La rupture de l’artère circonflexe postérieure","c":true},{"l":"D","t":"L’arrachement du petit trochanter","c":false},{"l":"E","t":"Un retard de réduction de plus de 24 heures","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Banque de QCM OTR","Banque de QCM OTR p.18"]'::jsonb),
(169, 19, 'Traumatologie', 'Ceinture scapulaire', NULL, true, true, 'Les complications des fractures de la diaphyse humérale compotent:', '[{"l":"A","t":"L’ouverture du foyer","c":true},{"l":"B","t":"La paralysie du nerf circonflexe","c":false},{"l":"C","t":"La luxation de l’épaule","c":false},{"l":"D","t":"La paralysie du nerf radial","c":true},{"l":"E","t":"La pseudarthrose","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(170, 19, 'Traumatologie', 'Ceinture scapulaire', NULL, false, true, 'Pour ce même patient le bilan radiologique doit comporter (cochez la ou les réponses justes)', '[{"l":"A","t":"Une incidence 3 ⁄4 interne de l’humérus","c":false},{"l":"B","t":"Une incidence 3 ⁄4 externe de l’humérus","c":false},{"l":"C","t":"Un profil axillaire de l’épaule","c":false},{"l":"D","t":"Une incidence de face de l’humérus","c":true},{"l":"E","t":"Une incidence de profil de l’humérus","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(171, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', NULL, false, true, 'Apres fracture de la diaphyse humérale, une complication neurologique est particulièrement fréquente, il s’agit: (citez la réponse juste)', '[{"l":"A","t":"De la paralysie du nerf circonflexe.","c":false},{"l":"B","t":"De la paralysie du nerf interosseux postérieur.","c":false},{"l":"C","t":"De la paralysie du nerf radial.","c":true},{"l":"D","t":"De la paralysie du nerf cubital.","c":false},{"l":"E","t":"De la paralysie du nerf médian","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(172, 18, 'Traumatologie', 'Amputations des membres', NULL, false, true, 'La paralysie sus citée se traduit cliniquement par (cochez la ou les réponses justes)', '[{"l":"A","t":"Un déficit des extenseurs de la main","c":true},{"l":"B","t":"Une anesthésie de la pulpe de l’index","c":false},{"l":"C","t":"Une anesthésie de la face dorsale de la première commissure.","c":true},{"l":"D","t":"Un déficit des muscles inter osseux de la main","c":false},{"l":"E","t":"Une anesthésie du moignon de l’épaule","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(173, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', NULL, true, true, 'Les complications des fractures de la diaphyse humérale comporte: (cochez les réponses justes)', '[{"l":"A","t":"L’ouverture du foyer","c":true},{"l":"B","t":"La paralysie du nerf circonflexe","c":false},{"l":"C","t":"La paralysie du nerf radial","c":true},{"l":"D","t":"La pseudarthrose","c":true},{"l":"E","t":"Toutes les réponses sont fausses","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(174, 19, 'Traumatologie', 'Ceinture scapulaire', NULL, false, true, 'Pour ce même patient, le bilan radiologique doit comporter: (la ou les réponses justes)', '[{"l":"A","t":"une incidence ¾ interne de l’humérus","c":false},{"l":"B","t":"une incidence ¾ externe de l’humérus","c":false},{"l":"C","t":"un profil axillaire de l’épaule","c":false},{"l":"D","t":"une incidence de face de l’humérus","c":true},{"l":"E","t":"une incidence de profil de l’humérus","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(175, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', NULL, false, true, 'Après la fracture de la diaphyse humérale, une complication neurologique est particulièrement fréquente, il s’agit:', '[{"l":"A","t":"de la paralysie du nerf circonflexe","c":false},{"l":"B","t":"de la paralysie du nerf interosseux postérieur","c":false},{"l":"C","t":"de la paralysie du nerf radial","c":true},{"l":"D","t":"de la paralysie du nerf cubital","c":false},{"l":"E","t":"de la paralysie du nerf médian","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(176, 18, 'Traumatologie', 'Amputations des membres', NULL, false, true, 'La paralysie suscitée se traduit uniquement par: (la ou les réponses justes)', '[{"l":"A","t":"un déficit des extenseurs de la main","c":true},{"l":"B","t":"une anesthésie de la pulpe de l’index","c":false},{"l":"C","t":"une anesthésie de la face dorsale de la première commissure","c":true},{"l":"D","t":"un déficit des muscles interosseux de la main","c":false},{"l":"E","t":"une anesthésie du moignon de l’épaule","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(177, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', NULL, true, true, 'Devant une fracture de la diaphyse humérale quel est la complication la plus fréquente ? cocher la réponse juste', '[{"l":"A","t":"paralysie du nerf circonflexe","c":false},{"l":"B","t":"paralysie du nerf médian","c":false},{"l":"C","t":"paralysie du nerf radial","c":true},{"l":"D","t":"paralysie du nerf ulnaire","c":false},{"l":"E","t":"paralysie du nerf fibulaire commun","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(178, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', NULL, false, true, 'La luxation antéro-interne de l’épaule se caractérise par tous les signes suivants sauf un. Indiquez lequel:', '[{"l":"A","t":"L’abduction irréductible","c":false},{"l":"B","t":"L’ecchymose brachio-thoracique","c":true},{"l":"C","t":"Le vide sous-acromial","c":false},{"l":"D","t":"Le coup de hache externe","c":false},{"l":"E","t":"Le comblement du sillon delto-pectoral","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(179, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', NULL, false, true, 'La complication la plus fréquente de la luxation de l’épaule touche:', '[{"l":"A","t":"Le nerf radial","c":false},{"l":"B","t":"Le nerf musculo-cutané","c":false},{"l":"C","t":"Le plexus brachial","c":false},{"l":"D","t":"Le nerf circonflexe","c":true},{"l":"E","t":"Le nerf cubital","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(180, 8, 'Traumatologie', 'Généralités sur les fractures de l’adulte', NULL, false, true, 'L’évolution d’une fracture de la clavicule vers la pseudarthrose:', '[{"l":"A","t":"Ne se voit jamais","c":false},{"l":"B","t":"Se voit surtout après traitement chirurgical","c":true},{"l":"C","t":"Ne se voit jamais après un traitement orthopédique","c":false},{"l":"D","t":"Se voit surtout en l’absence de traitement","c":false},{"l":"E","t":"N’a pas de compétences fonctionnelles","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(181, 19, 'Traumatologie', 'Ceinture scapulaire', NULL, false, true, 'Le siège anatomique le plus fréquent des fractures de la clavicule se situe: La RJ', '[{"l":"A","t":"Au 1/3 interne","c":false},{"l":"B","t":"Au 1/3 moyen","c":true},{"l":"C","t":"Au 1/4 externe","c":false},{"l":"D","t":"Plaque coracoïdienne","c":false},{"l":"E","t":"Zone d''insertion du ligament costo-chondro-claviculaire","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(182, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', NULL, false, true, 'La luxation de l’épaule est le plus souvent:La RJ', '[{"l":"A","t":"Antéro-interne sous claviculaire","c":false},{"l":"B","t":"Interne sous glénoïdienne","c":false},{"l":"C","t":"Antéro-interne sous coracoïdienne","c":true},{"l":"D","t":"Postérieure","c":false},{"l":"E","t":"Supérieure","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(183, 19, 'Traumatologie', 'Ceinture scapulaire', NULL, false, true, 'Une luxation acromio-claviculaire de stade III se définit par: (La ou les réponses justes)', '[{"l":"A","t":"Une lésion des ligaments conoïdes et trapézoïdes","c":true},{"l":"B","t":"Une lésion de la sangle musculaire deltoïdo- trapézoïdienne","c":true},{"l":"C","t":"Une lésion du ligament acromio-coracoïdien","c":false},{"l":"D","t":"Une lésion des moyens d’union intrinsèque de l’articulation acromio-claviculaire","c":true},{"l":"E","t":"Une atteinte des insertions claviculaires des petits et grands pectoraux","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(184, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', NULL, false, true, 'Indiquez parmi les suivants, les signes cliniques qui permettent d’affirmer l’existence d’une luxation acromio-claviculaire:', '[{"l":"A","t":"Le signe de l’épaulette","c":false},{"l":"B","t":"Un tiroir antérieur claviculaire","c":true},{"l":"C","t":"La mobilité de la clavicule en touche de piano","c":true},{"l":"D","t":"La douleur exquise à l’extrémité externe de la clavicule","c":true},{"l":"E","t":"Le vide sous-acromion antérieur","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(185, 19, 'Traumatologie', 'Ceinture scapulaire', NULL, false, true, 'Une fracture du tiers moyen de la clavicule: (Réponse juste)', '[{"l":"A","t":"Entraîne souvent des lésions de la veine sous- clavière","c":false},{"l":"B","t":"Consolide en moyenne en 90 jours","c":false},{"l":"C","t":"Laisse dans la règle un cal en baïonnette exubérant","c":true},{"l":"D","t":"Relève d’une réduction anatomique avec une contention interne solide","c":false},{"l":"E","t":"Est traitée par un bandage coude au corps","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(186, 19, 'Traumatologie', 'Ceinture scapulaire', NULL, false, true, 'Un patient âgé de 25 ans qui présente après une chute de cheval avec réception sur l’épaule droite, se fracture du tiers interne de la clavicule très déplace à bords très aigues. Que faut-il craindre ?', '[{"l":"A","t":"Une lésion du circonflexe.","c":false},{"l":"B","t":"Une lésion de l’artère axillaire","c":false},{"l":"C","t":"Une lésion de l’artère sous Clavière","c":true},{"l":"D","t":"Une lésion du plexus brachial","c":false},{"l":"E","t":"Un pneumothorax","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(187, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', NULL, false, true, 'Le diagnostic clinique d’une luxation antérieure de l’épaule se base sur:( Cochez-la (les) proposition(s) fausses).', '[{"l":"A","t":"Signe de l’épaulette","c":false},{"l":"B","t":"Vacuité de la glène de l’omoplate","c":false},{"l":"C","t":"Position anormale de la tête humérale","c":false},{"l":"D","t":"L’abduction réductible du bras","c":true},{"l":"E","t":"Le signe de Berger","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(188, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', NULL, false, true, 'Le mécanisme lésionnel responsable d’une épaule pseudo-paralytique est:', '[{"l":"A","t":"Une atteinte du nerf circonflexe responsable de l’innervation de l’épaule","c":false},{"l":"B","t":"Une rupture des tendons de la coiffe des rotateurs","c":true},{"l":"C","t":"Une arthropathie destructrice de l’articulation gléno-humorale","c":false},{"l":"D","t":"Une fracture de l’extrémité supérieure de l’humérus","c":false},{"l":"E","t":"Une luxation de la tête humorale","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(189, 20, 'Traumatologie', 'Épaule douloureuse (pathologie péri-articulaire)', NULL, true, true, 'Concernant la bursite aigue sous acromio- deltoïdienne: La ou Les RF(s)', '[{"l":"A","t":"Il s’agit d’une complication d’une tendinopathie calcifiante de la coiffe des rotateurs","c":false},{"l":"B","t":"Les mobilités active et passive de l’épaule sont conservées.","c":true},{"l":"C","t":"Le bilan radiographique est souvent normal","c":true},{"l":"D","t":"Une chondrocalcinose peut être évoquée.","c":false},{"l":"E","t":"Le traitement médical est toujours efficace.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(190, 20, 'Traumatologie', 'Ceinture scapulaire', NULL, true, true, 'Après une rupture de la coiffe des rotateurs non opérée: la ou les RF', '[{"l":"A","t":"Les ultrasons sont à visée antalgique","c":false},{"l":"B","t":"Le recentrage de la tête humérale est passif","c":false},{"l":"C","t":"La récupération des amplitudes articulaires passives est proscrite","c":true},{"l":"D","t":"L’élévation antérieure de l’épaule est autorisée","c":true},{"l":"E","t":"Les mouvements répétés sont proscrits","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(191, 29, 'Traumatologie', 'Algoneurodystrophie', NULL, false, true, 'Un patient âgé de 60ans, se présente aux urgences pour impotence fonctionnelle totale de son épaule droite d’apparition progressive. L’examen clinique met en évidence une mobilité passive conservée et une limitation de la mobilité active. Quel est votre diagnostic ?', '[{"l":"A","t":"Tendinopathie chronique du supra-épineux","c":false},{"l":"B","t":"Rupture totale de la coiffe des rotateurs","c":true},{"l":"C","t":"Bursite algue micro-cristalline","c":false},{"l":"D","t":"Algodystrophie de l’épaule droite","c":false},{"l":"E","t":"Une névralgie cervico-brachiale droite","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(192, 20, 'Traumatologie', 'Épaule douloureuse (pathologie péri-articulaire)', NULL, false, true, 'Quelle est la manœuvre du testing de la coiffe qui met en évidence une atteinte du supra spinatus?', '[{"l":"A","t":"Manœuvre du lift off test de Gerber","c":false},{"l":"B","t":"Manœuvre de Patte","c":true},{"l":"C","t":"Manœuvre de Yocum","c":false},{"l":"D","t":"Manœuvre de Jobe","c":false},{"l":"E","t":"Palm up test","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(193, 29, 'Traumatologie', 'Algoneurodystrophie', NULL, false, true, 'Un patient âgé de 60 ans, se présente aux urgences pour une impotence fonctionnelle totale de son épaule droite d’apparition brutale. Toute tentative de mobilisation est très douloureuse voire impossible. Quel est votre diagnostic ?', '[{"l":"A","t":"tendinopathie chronique du supra-épineux","c":false},{"l":"B","t":"rupture totale de la coiffe des rotateurs","c":false},{"l":"C","t":"bursite aiguë micro cristalline","c":true},{"l":"D","t":"algodystrophie de l’épaule droite","c":false},{"l":"E","t":"une névralgie cervico-brachiale droite","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(194, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', NULL, false, true, 'Quel est le mécanisme incriminé au cours d’une épaule de pseudo-paralytique avec impossibilité de lever le bras passivement au-dessus de l’horizontale:', '[{"l":"A","t":"une paralysie du nerf circonflexe","c":false},{"l":"B","t":"une rupture du tendon du supra épineux","c":true},{"l":"C","t":"un conflit antéro-interne","c":false},{"l":"D","t":"une rétraction de la capsule articulaire","c":false},{"l":"E","t":"une bursite aiguë sous acromio-deltoïdienne","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(195, 20, 'Traumatologie', 'Épaule douloureuse (pathologie péri-articulaire)', NULL, false, true, 'Une épaule douloureuse hyperalgique: (la ou les réponses justes)', '[{"l":"A","t":"réalise un tableau aigu avec réaction fébrile","c":true},{"l":"B","t":"est du à la migration d’une calcification tendineuse de la bourse séreuse sous acromio-deltoïdienne","c":true},{"l":"C","t":"la mobilité passive est conservée","c":false},{"l":"D","t":"la ponction articulaire est parfois nécessaire au moindre doute","c":true},{"l":"E","t":"le diagnostic est confirmé par la radiographie","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(196, 20, 'Traumatologie', 'Épaule douloureuse (pathologie péri-articulaire)', NULL, false, true, 'Concernant la bursite aigue de l’épaule, quel est l’examen complémentaire qui permet de son diagnostic:', '[{"l":"A","t":"Radiographies standard","c":true},{"l":"B","t":"Echographie","c":false},{"l":"C","t":"Arthrographie","c":false},{"l":"D","t":"Scintigraphie osseuse E Imagerie par résonance magnétique","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(197, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', NULL, true, true, 'Quel est le mécanisme incriminé au cours d’une manœuvre de Neer positive ?', '[{"l":"A","t":"Une paralysie du nerf circonflexe","c":false},{"l":"B","t":"Une rupture du tendon supra épineux","c":true},{"l":"C","t":"Un conflit sous acromial","c":false},{"l":"D","t":"Une rétraction e la capsule articulaire","c":true},{"l":"E","t":"Une bursite aigue sous acromio- deltoïdienne.","c":false},{"l":"A","t":"la limitation des mobilités passive et la normalité Des mobilités active et en faveur du diagnostic","c":false},{"l":"B","t":"l’examen neurologique doit être normal","c":true},{"l":"C","t":"correspond le plus souvent à une rupture totale du tendon du supra-épineux","c":false},{"l":"D","t":"la radiographie standard montre parfois une ascension de la tête humérale","c":true},{"l":"E","t":"l’échographie permet de déterminer le tendon rompu","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(198, 20, 'Traumatologie', 'Ceinture scapulaire', NULL, true, true, 'Quelles sont les caractéristiques d’une épaule pseudo paralytique ?', '[{"l":"A","t":"Très douloureuse.","c":false},{"l":"B","t":"Touche généralement le sujet Agé.","c":true},{"l":"C","t":"Entraine une limitation des mouvements passifs de l’épaule","c":false},{"l":"D","t":"Entraine une limitation des mouvements actif de l’épaule","c":true},{"l":"E","t":"Pincement de l’espace acromio-humérale sur la radiographie","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(199, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', NULL, false, true, 'Un patient, victime d’un accident de la voie publique est ramené aux urgences, l’examen clinique note une déformation douloureuse avec une tuméfaction du bras évoquant une fracture de la diaphyse humérale. Une complication neurologique est particulièrement fréquente, il s’agit de:', '[{"l":"A","t":"Paralysie du nerf circonflexe.","c":false},{"l":"B","t":"Paralysie du plexus brachial.","c":false},{"l":"C","t":"Paralysie du nerf radial.","c":true},{"l":"D","t":"Paralysie du nerf ulnaire (cubital)","c":false},{"l":"E","t":"Paralysie du nerf fibulaire commun (Sciatique poplité externe)","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(200, 19, 'Traumatologie', 'Ceinture scapulaire', NULL, false, true, 'Chez ce patient, pour diagnostiquer cette complication neurologique, il est impératif de:', '[{"l":"A","t":"Tester les muscles releveurs de l’épaule.","c":false},{"l":"B","t":"Vérifier l’intégrité du revêtement cutané,","c":false},{"l":"C","t":"Palper les pouls radial et cubital homolatéraux.","c":false},{"l":"D","t":"Tester les muscles extenseurs du poignet et de la main.","c":true},{"l":"E","t":"Faire radio de la main et du poignet.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb);
